    css: "/* From Uiverse.io by Codewithvinay - Tags: glassmorphism, card */\n.box {\n position: relative;\n width: 220px;\n height: 300px;\n display: flex;\n justify-content: center;\n align-items: center;\n transition: 0.5s;\n z-index: 1;\n}\n\n.box::before {\n content: ' ';\n position: absolute;\n top: 0;\n left: 50px;\n width: 50%;\n height: 100%;\n text-decoration: none;\n background: #fff;\n border-radius: 8px;\n transform: skewX(15deg);\n transition: 0.5s;\n}\n\n.box::after {\n content: '';\n position: absolute;\n top: 0;\n left: 50;\n width: 50%;\n height: 100%;\n background: #fff;\n border-radius: 8px;\n transform: skewX(15deg);\n transition: 0.5s;\n filter: blur(30px);\n}\n\n.box:hover:before,\n.box:hover:after {\n transform: skewX(0deg) scaleX(1.3);\n}\n\n.box:before,\n.box:after {\n background: linear-gradient(315deg, #ffbc00, #ff0058)\n}\n\n.box span {\n display: block;\n position: absolute;\n top: 0;\n left: 0;\n right: 0;\n bottom: 0;\n z-index: 5;\n pointer-events: none;\n}\n\n.box span::before {\n content: '';\n position: absolute;\n top: 0;\n left: 0;\n width: 0;\n height: 0;\n border-radius: 8px;\n background: rgba(255, 255, 255, 0.1);\n backdrop-filter: blur(10px);\n opacity: 0;\n transition: 0.1s;\n animation: animate 2s ease-in-out infinite;\n box-shadow: 0 5px 15px rgba(0,0,0,0.08)\n}\n\n.box span::before {\n top: -40px;\n left: 40px;\n width: 50px;\n height: 50px;\n opacity: 1;\n}\n\n.box span::after {\n content: '';\n position: absolute;\n bottom: 0;\n right: 0;\n width: 100%;\n height: 100%;\n border-radius: 8px;\n background: rgba(255, 255, 255, 0.1);\n backdrop-filter: blur(10px);\n opacity: 0;\n transition: 0.5s;\n box-shadow: 0 5px 15px rgba(0,0,0,0.08);\n animation-delay: -1s;\n}\n\n.box span:after {\n bottom: -40px;\n right: 40px;\n width: 50px;\n height: 50px;\n opacity: 1;\n}\n\n.box .content {\n position: relative;\n width: 190px;\n height: 254px;\n padding: 20px 40px;\n background: rgba(255, 255, 255, 0.05);\n backdrop-filter: blur(10px);\n box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);\n border-radius: 8px;\n z-index: 1;\n transform: 0.5s;\n color: #fff;\n display: flex;\n justify-content: center;\n align-items: center;\n}\n\n.box .content h2 {\n font-size: 20px;\n color: #fff;\n margin-bottom: 10px;\n}",
