    css: "/* From Uiverse.io by Gerente-S4V1T4R - Tags: card */\n.container {\n  --background: linear-gradient(to left, #880505 0%, #f36b11 100%);\n  width: 190px;\n  height: 254px;\n  padding: 4px;\n  border-radius: 5px;\n  overflow: visible;\n  display: flex;\n  align-items: center;\n  background: var(--background);\n  position: relative;\n}\n\n.container .box {\n  position: relative;\n  width: 190px;\n  height: 244px;\n  background: #1b1b1b;\n  display: -webkit-box;\n  display: -ms-flexbox;\n  display: flex;\n  -webkit-box-pack: center;\n  -ms-flex-pack: center;\n  justify-content: center;\n  -webkit-box-align: center;\n  -ms-flex-align: center;\n  align-items: center;\n  border-radius: 10px;\n}\n\n.container .box .content {\n  position: relative;\n  display: -webkit-box;\n  display: -ms-flexbox;\n  display: flex;\n  -webkit-box-pack: center;\n  -ms-flex-pack: center;\n  justify-content: center;\n  -webkit-box-align: center;\n  -ms-flex-align: center;\n  align-items: center;\n  -webkit-box-orient: vertical;\n  -webkit-box-direction: normal;\n  -ms-flex-direction: column;\n  flex-direction: column;\n  text-align: center;\n  gap: 20px;\n  padding: 0 20px;\n  width: 100%;\n  height: 100%;\n  overflow: hidden;\n}\n\n.container .box .content .icon {\n  width: 50px;\n  height: 50px;\n  -webkit-box-shadow: 0 0 0 4px #e6e6e6,\n    0 0 0 6px rgb(212, 10, 10);\n  box-shadow: 0 0 0 4px #e6e6e6,\n    0 0 0 6px rgb(212, 10, 10);\n  display: -webkit-box;\n  display: -ms-flexbox;\n  display: flex;\n  -webkit-box-pack: center;\n  -ms-flex-pack: center;\n  justify-content: center;\n  -webkit-box-align: center;\n  -ms-flex-align: center;\n  align-items: center;\n  font-size: 2.5em;\n  -webkit-transition: 0.5s ease-in-out;\n  transition: 0.5s ease-in-out;\n}\n\n.container .box::before {\n  content: '';\n  position: absolute;\n  inset: -10px 50px;\n  border-top: 4px solid rgb(99, 89, 247);\n  z-index: -1;\n  border-bottom: 4px solid rgb(65, 44, 250);\n  z-index: -1;\n  z-index: -1;\n  -webkit-transform: skewY(15deg);\n  -ms-transform: skewY(15deg);\n  transform: skewY(15deg);\n  -webkit-transition: 0.5s ease-in-out;\n  transition: 0.5s ease-in-out;\n}\n\n.container .box:hover::before {\n  -webkit-transform: skewY(0deg);\n  -ms-transform: skewY(0deg);\n  transform: skewY(0deg);\n  inset: -10px 40px;\n}\n\n.container .box::after {\n  content: '';\n  position: absolute;\n  inset: 60px -10px;\n  border-left: 4px solid #880505;\n  z-index: -1;\n  border-right: 4px solid #aa551d;\n  z-index: -1;\n  -webkit-transform: skew(15deg);\n  -ms-transform: skew(15deg);\n  transform: skew(15deg);\n  -webkit-transition: 0.5s ease-in-out;\n  transition: 0.5s ease-in-out;\n}\n\n.container .box:hover::after {\n  -webkit-transform: skew(0deg);\n  -ms-transform: skew(0deg);\n  transform: skew(0deg);\n  inset: 40px -10px;\n}\n\n.container .box .content {\n  border-radius: 50%;\n}",
