    css: "/* From Uiverse.io by Javierrocadev - Source: Javierrocadev - Tags: phone, card hover, 3d card */\n.card {\n  width: 164px;\n  height: 276px;\n  background: rgb(0, 0, 0);\n  border: 3px solid rgb(17, 4, 94);\n  border-radius: 15px;\n  position: relative;\n  padding: 5px;\n  display: flex;\n  flex-direction: column;\n  gap: 22px;\n  transition: all 1s ease;\n  color: antiquewhite;\n}\n\n.card::before {\n  content: \"\";\n  width: 10px;\n  height: 10px;\n  position: absolute;\n  bottom: 10px;\n  right: 77px;\n  border-radius: 50%;\n  background-color: rgb(17, 4, 94);\n}\n\n.card__date {\n  display: flex;\n  flex-direction: column;\n  margin-top: 30px;\n}\n\n.time {\n  font-size: 2em;\n}\n\n.popup {\n  background-color: #444746;\n  border-radius: 5px;\n  display: flex;\n  flex-direction: column;\n  font-size: .8em;\n  padding: 3px;\n}\n\n.popup .title {\n  font-size: 9px;\n  color: #9cbde2;\n}\n\n.card__date , .popup {\n  opacity: 0;\n  transition: all .5s ease;\n}\n\n.card:hover {\n  transform: rotate3d(5, 5, 10, -45deg);\n}\n\n.card:hover .card__date , .card:hover .popup {\n  opacity: 1;\n}",
