    css: "/* From Uiverse.io by Javierrocadev - Source: twitter.com - Tags: twitter, card, white card, round card */\n.card {\n  width: 350px;\n  height: 160px;\n  background: #f7f9f9;\n  padding: 10px;\n  border-radius: 16px;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-evenly;\n  align-items: flex-start;\n}\n\n.card__title {\n  font-size: 1.4em;\n  font-weight: 800;\n}\n\n.card__text {\n  font-weight: 500;\n}\n\n.card__button {\n  cursor: pointer;\n  background-color: rgb(15, 20, 25);\n  color: #f7f9f9;\n  font-size: 1.15em;\n  border: none;\n  padding: 5px 15px;\n  border-radius: 15px;\n}\n\n.card__button:hover {\n  background-color: #272C30;\n}",
