    author: "JaydipPrajapati1910",
    source: "galaxy",
    html: "<ul>\n  <li>\n    <a href=\"#\">\n      <span>\n     Hover Me\n      </span>\n    </a>\n  </li> \n  </ul>",
    css: "/* From Uiverse.io by JaydipPrajapati1910 - Tags: 3d, card, shadow, box-shadow */\nul {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  display: flex;\n  margin: 0;\n  padding: 0;\n}\n\nul li {\n  list-style: none;\n  margin: 0 5px;\n}\n\nul li a span {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  color: #fff;\n  letter-spacing: 1px;\n  transition: .5s;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  text-align: center;\n  font-family: sans-serif;\n  font-size: px;\n  font-weight: 900;\n}\n\nul li a {\n  text-decoration: none;\n  display: block;\n  width: 200px;\n  height: 250px;\n  background: #333;\n  padding-left: 20px;\n  transform: rotate(-30deg) skew(25deg) translate(0,0);\n  transition-duration: .5s;\n  box-shadow: -20px 20px 10px rgba(0,0,0,.5);\n}\n\nul li a:before {\n  content: '';\n  position: absolute;\n  top: 10px;\n  left: -20px;\n  height: 100%;\n  width: 20px;\n  background: #444;\n  transition-duration: .5s;\n  transform: rotate(0deg) skewY(-45deg);\n}\n\nul li a:after {\n  content: '';\n  position: absolute;\n  bottom: -20px;\n  left: -10px;\n  height: 20px;\n  width: 100%;\n  background: #444;\n  transition-duration: .5s;\n  transform: rotate(0deg) skewX(-45deg);\n}\n\nul li a:hover {\n  transform: rotate(-30deg) skew(25deg) translate(20px,-15px);\n  box-shadow: -50px 50px 50px rgba(0,0,0,.5);\n}\n\nul li:hover span {\n  color: #fff;\n}\n\nul li:hover:nth-child(1) a {\n  background: #00aced;\n}\n\nul li:hover:nth-child(1) a:before {\n  background: #097aa5;\n}\n\nul li:hover:nth-child(1) a:after {\n  background: #53b9e0;\n}",
