    css: "/* From Uiverse.io by JesusRafaelNavaCruz - Tags: slider, sliding, slide */\n.container {\n  overflow: auto;\n  display: flex;\n  scroll-snap-type: x mandatory;\n  width: 90%;\n  margin: 0 auto;\n  padding: 0 15px;\n}\n\n.card {\n  background: rgba(255, 255, 255, 0.25);\n  box-shadow: 0 8px 32px 0 rgba(31, 38, 135, 0.37);\n  backdrop-filter: blur(7px);\n  -webkit-backdrop-filter: blur(7px);\n  border-radius: 10px;\n  padding: 2rem;\n  margin: 1rem;\n  width: 100%;\n}\n\n.title {\n  width: 100%;\n  display: inline-block;\n  word-break: break-all;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  text-align: center;\n  margin: 1rem auto;\n}",
