    source: "galaxy",
    html: "<div class=\"card card-5\">\n  <div class=\"card__icon\">\ud83c\udfc6</div>\n  <p class=\"card__exit\">\u203b</p>\n  <div class=\"text\">Ut aliquip ex ea commodo consequat. Duis aute irure dolor</div>\n  <p class=\"card__apply\">\n    <a class=\"card__link\" href=\"#\">Apply Now <i class=\"fas fa-arrow-right\"></i></a>\n  </p>\n</div>",
    css: "/* From Uiverse.io by Shoh2008 - Tags: card */\n.card {\n  margin: 20px;\n  padding: 20px;\n  width: 300px;\n  min-height: 200px;\n  display: grid;\n  grid-template-rows: 20px 50px 1fr 50px;\n  border-radius: 10px;\n  box-shadow: 0px 6px 10px rgba(0, 0, 0, 0.25);\n  transition: all 0.2s;\n}\n\n.card:hover {\n  box-shadow: 0px 6px 10px rgba(0, 0, 0, 0.4);\n  transform: scale(1.01);\n}\n\n.card__link,\n.card__exit,\n.card__icon {\n  position: relative;\n  text-decoration: none;\n  color: rgba(255, 255, 255, 0.9);\n}\n\n.card__link::after {\n  position: absolute;\n  top: 25px;\n  left: 0;\n  content: \"\";\n  width: 0%;\n  height: 3px;\n  background-color: rgba(255, 255, 255, 0.6);\n  transition: all 0.5s;\n}\n\n.card__link:hover::after {\n  width: 100%;\n}\n\n.text {\n  color: white;\n}\n\n.card__exit {\n  grid-row: 1/2;\n  justify-self: end;\n}\n\n.card__icon {\n  grid-row: 2/3;\n  font-size: 30px;\n}\n\n.card__title {\n  grid-row: 3/4;\n  font-weight: 400;\n  color: #ffffff;\n}\n\n.card__apply {\n  grid-row: 4/5;\n  align-self: center;\n}\n\n.card-5 {\n  background: radial-gradient(#f588d8, #c0a3e5);\n}\n\n@media (max-width: 1600px) {\n  .cards {\n    justify-content: center;\n  }\n}",
