    source: "galaxy",
    html: "<div class=\"flip\">\n    <div class=\"content\">\n        <div class=\"front\">\n            <h2>Front</h2>\n            <p>Front Description</p>\n        </div>\n        <div class=\"back\">\n            <h2>Back</h2>\n            <p>Back Description</p>\n        </div>\n    </div>\n</div>",
    css: "/* From Uiverse.io by david-mohseni - Tags: card */\n.flip {\n  box-shadow: 0 0 10px rgba(128, 128, 128, 0.5);\n  padding: 1em;\n  width: 190px;\n  height: 254px;\n  transform-style: preserve-3d;\n  transition: 3s ease;\n}\n\n.flip:hover {\n  transform: rotateY(180deg);\n}\n/* Content */\n.flip .content {\n  transform-style: preserve-3d;\n}\n\n.flip .back, .flip .front {\n  transform-style: preserve-3d;\n  backface-visibility: hidden;\n  display: flex;\n  flex-direction: column;\n}\n\n.flip .back {\n  transform: rotateY(180deg);\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n}\n\n.flip h2,\n.flip p {\n  transform: translateZ(90px);\n  text-shadow: 0 0 3px black;\n  text-align: center;\n}\n\n.flip h2 {\n  font-size: 3em;\n  color: #fff;\n  letter-spacing: 1px;\n}\n\n.flip p {\n  font-size: 1em;\n  color: #eee;\n  line-height: 1.6em;\n}\n\n.flip::before,\n.flip::after {\n  content: \"\";\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  position: absolute;\n  background-image: linear-gradient(purple, red);\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: cover;\n  transform: rotateY(180deg)translateZ(1px);\n}\n\n.flip::before {\n  transform: none;\n  background-image: linear-gradient(violet, orange);\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: cover;\n}",
