    css: "/* From Uiverse.io by htwarriors108 - Tags: gradient, card, hover, flip, neon, blur filter, animated, hover effect, card flip */\n.one-div {\n  background-color: #fff;\n  width: 190px;\n  height: 254px;\n  box-shadow: 0 0 0.5em rgba(255, 255, 255, 0.5);\n  border: 1px solid rgba(255, 255, 255, 0.6);\n  border-radius: 12px;\n  transition: 0.5s;\n  cursor: pointer;\n  transform: rotateX(-55deg) rotateY(15deg) rotateZ(60deg);\n  color: #fff;\n}\n\n.one-div:active {\n  scale: 1.1;\n  rotate: 5deg;\n}\n\n@keyframes animate {\n  0% {\n    opacity: 0.3;\n  }\n\n  80% {\n    opacity: 1;\n  }\n\n  100% {\n    opacity: 0.3;\n  }\n}\n\n.one-div:hover {\n  transform: rotate(0deg);\n  opacity: 1;\n}\n\n.one-div, .one-div::before {\n  background: linear-gradient(43deg, rgb(65, 88, 208) 0%, rgb(200, 80, 192) 46%, rgb(255, 204, 112) 100%);\n}\n\n.one-div::before {\n  content: '';\n  width: 120%;\n  height: 110%;\n  z-index: -1;\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  border-radius: 15px;\n  transform: translate(-50%, -50%);\n  filter: blur(30px);\n  animation: animate 5s linear infinite;\n}\n\n.one-div::after {\n  content: 'Hover Me';\n  width: 100%;\n  height: 100%;\n  font-size: 2em;\n  font-weight: 800;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}",
