    css: "/* From Uiverse.io by javadpg - Tags: card, hover, stitched, transition, css, card hover */\n.card {\n  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;\n  position: relative;\n  color: #fff;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 300px;\n  height: 350px;\n  border-radius: 6px;\n  transition: .3s;\n  background-color: #000;\n}\n\n.card-p {\n  position: absolute;\n  text-align: center;\n}\n\n.card::after {\n  content: \"\";\n  position: absolute;\n  z-index: -6;\n  border-radius: 6px;\n  width: 320px;\n  height: 370px;\n  background-color: #8EC5FC;\n  transition: .7s;\n  background-image: linear-gradient(62deg, #8EC5FC 0%, #E0C3FC 100%);\n}\n\n.card-countent {\n  padding: 20px;\n  text-align: center;\n  color: transparent;\n  transition: all .7s;\n  opacity: 0;\n}\n\n.card:hover {\n  transition: .7s;\n  transform: rotate(180deg);\n}\n\n.card:hover > .card-p {\n  color: transparent;\n}\n\n.card:hover > .card-countent {\n  opacity: 1;\n  color: #000;\n  transform: rotate(-180deg);\n}",
