    source: "galaxy",
    html: "<div class=\"cards\">\n  <div class=\"card red\">\n    <p class=\"tip\">Hover Me</p>\n  </div>\n  <div class=\"card blue\">\n    <p class=\"tip\">Hover Me</p>\n  </div>\n  <div class=\"card green\">\n    <p class=\"tip\">Hover Me</p>\n  </div>\n</div>",
    css: "/* From Uiverse.io by mohamedkhire  - Tags: glassmorphism, card, box, transition, card template, cool card */\n.card::before {\n  border-radius: 50%;\n  width: 7rem;\n  height: 7rem;\n  top: 20%;\n}\n\n.card::before,\n.card::after {\n  content: \"\";\n  background-color: #7090fa4b;\n  position: absolute;\n  filter: blur(10px);\n}\n\n.cards {\n  display: flex;\n  gap: 40px;\n}\n\n.cards .red,\n.cards .blue,\n.cards .green {\n  width: 200px;\n  height: 180px;\n  font-family: \"CustomFont\", Arial, Helvetica, sans-serif;\n  font-size: 24px;\n  font-weight: 600;\n  backdrop-filter: blur(30px);\n  background-color: rgba(65, 65, 65, 0.11);\n  border: 1px solid rgba(144, 161, 255, 0.171);\n}\n\n.cards .card {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-direction: column;\n  border-radius: 10px;\n  color: rgb(0, 0, 0);\n  cursor: pointer;\n  transition: 400ms;\n}\n\n.cards .card p.tip {\n  font-size: 1em;\n  font-weight: 700;\n}\n\n.cards .card p.second-text {\n  font-size: 0.7em;\n}\n\n.cards .card:hover {\n  transform: scale(1.1, 1.1);\n}\n\n.cards:hover > .card:not(:hover) {\n  filter: blur(5px);\n  transform: scale(0.9, 0.9);\n}",
