    css: "/* From Uiverse.io by roroland  - Tags: 3d, pink, button, card, animated */\n.one-div {\n  --color1: #db41a5;\n  --color2: pink;\n  --color3: #fff;\n  --color4: #ffaae2;\n  --time: 5;\n  display: grid;\n  grid-template-columns: 1fr;\n  grid-template-rows: 1fr;\n  align-items: center;\n  justify-content: center;\n  padding: 1em;\n  width: auto;\n  height: 100%;\n  position: relative;\n  transition: all 1s ease-out;\n  transform: perspective(400px);\n  transform-style: preserve-3d;\n  z-index: 0;\n}\n\n.one-div:hover {\n  cursor: pointer;\n  filter: drop-shadow(0px 0px 100px var(--color2));\n  scale: 1.2;\n}\n\n.one-div:hover::after {\n  scale: 0;\n  opacity: 0;\n}\n\n.one-div:hover::before {\n  color: var(--color4);\n  box-shadow: 0px 0px 20px 5px rgba(0,0,0, .5), 0px 3px 50px rgba(0,0,0, .15), inset 0 0 1px 1px #000;\n  text-shadow: 0 1px 5px #000;\n}\n\n.one-div:active {\n  transition: all .1s ease-out;\n  scale: .99;\n}\n\n.one-div:active::before {\n  transition: all .1s ease-out;\n  color: white;\n}\n\n.one-div::after,\n.one-div::before {\n  padding: 1em;\n  grid-column: 1/-1;\n  grid-row: 1 / 1;\n  position: relative;\n  transition: all 1s ease-out .3s;\n}\n\n.one-div::before {\n  animation: fade calc(var(--time) * 1s) ease-out infinite calc(var(--time) * .5s);\n  content: 'Single div button';\n  border-radius: 4px;\n  background-image: linear-gradient(to bottom, var(--color1) 30%, var(--color2) 95%, var(--color3) 99%);\n}\n\n.one-div::after {\n  animation: rotate calc(var(--time) * 1s) ease-out infinite;\n  display: block;\n  width: calc(100% - 2rem);\n  outline-color: var(--color4);\n  outline-width: .5em;\n  outline-offset: .9em;\n  outline-style: solid;\n  content: '';\n  z-index: -1;\n}\n\n@keyframes rotate {\n  0% {\n    rotate: x -90deg;\n  }\n\n  0%, 50% {\n    filter: blur(0px) drop-shadow(0px 0px 60px var(--color3)) opacity(100%);\n  }\n\n  100% {\n    rotate: x 90deg;\n    filter: blur(4px) drop-shadow(0px 0px 30px var(--color2)) opacity(80%);\n  }\n}\n\n@keyframes fade {\n  0%, 100% {\n    opacity: 1;\n  }\n\n  50% {\n    opacity: 0.9;\n  }\n}",
