    css: "/* From Uiverse.io by ClawHack1 - Tags: login, card */\n.login-card {\n  background-color: #f8f8f8;\n  border-radius: 10px;\n  box-sizing: border-box;\n  padding: 20px;\n  max-width: 400px;\n  box-shadow: 0px 5px 10px rgba(0, 0, 0, 0.1);\n}\n\n.card-header {\n  text-align: center;\n  margin-bottom: 20px;\n}\n\n.card-header h1 {\n  font-size: 2em;\n  color: #333;\n  text-shadow: 1px 1px #ddd;\n}\n\n.form-group {\n  margin-bottom: 10px;\n}\n\n.form-group label {\n  display: block;\n  font-size: 1.2em;\n  color: #555;\n  margin-bottom: 10px;\n}\n\ninput[type=\"text\"],\ninput[type=\"email\"],\ninput[type=\"password\"] {\n  box-sizing: border-box;\n  padding: 10px;\n  border-radius: 5px;\n  border: none;\n  background-color: #f0f0f0;\n  font-size: 1.2em;\n  color: #555;\n  box-shadow: inset 0px 2px 5px rgba(0, 0, 0, 0.1);\n  transition: box-shadow 0.3s ease;\n}\n\ninput[type=\"text\"]:focus,\ninput[type=\"email\"]:focus,\ninput[type=\"password\"]:focus {\n  box-shadow: inset 0px 2px 5px rgba(0, 0, 0, 0.3);\n  outline: none;\n}\n\ninput[type=\"submit\"] {\n  background-color: #007bff;\n  border: none;\n  border-radius: 5px;\n  color: #fff;\n  cursor: pointer;\n  font-size: 1.2em;\n  padding: 10px;\n  transition: background-color 0.3s ease;\n}\n\ninput[type=\"submit\"]:hover {\n  background-color: #0069d9;\n}\n\n.login-button {\n  background-color: #007bff;\n  border: none;\n  border-radius: 5px;\n  color: #fff;\n  cursor: pointer;\n  font-size: 1.2em;\n  padding: 10px;\n  width: 100%;\n  transition: background-color 0.3s ease;\n  transition: 0.25s;\n}\n\n.login-button:hover {\n  background-color: #0069d9e7;\n  -webkit-box-shadow: 0px 0px 30px 0px rgba(0,105,217,1);\n  -moz-box-shadow: 0px 0px 30px 0px rgba(0,105,217,1);\n  box-shadow: 0px 0px 30px 0px rgba(0,105,217,1);\n}",
