    css: "/* From Uiverse.io by ElektroRaks - Tags: card, polygon, blur filter, text animation, rotate, clip-path */\n.card {\n  width: 11.875em;\n  height: 15.875em;\n  background: linear-gradient(135deg, #1afbf0, #da00ff);\n  background-position: center;\n  background-size: cover;\n  background-repeat: no-repeat;\n}\n\n.box {\n  width: 100%;\n  height: 100%;\n  background-color: rgba(255, 255, 255, 0.074);\n  -webkit-backdrop-filter: blur(20px);\n  backdrop-filter: blur(20px);\n}\n\n.content {\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  width: 100%;\n  height: 100%;\n  padding: 10px;\n  background-position: center;\n  background-size: cover;\n  background-repeat: no-repeat;\n  clip-path: polygon(54% 27%, 100% 50%, 100% 100%, 51% 74%, 0 50%, 0% 0%);\n  transition: 0.5s;\n  line-height: 1.2;\n}\n\n.card-title {\n  width: 100%;\n  font-weight: bold;\n  color: white;\n  display: block;\n  padding-top: 6.3em;\n  font-size: 1.2em;\n  transform: rotate(34deg);\n  transition: 0.5s;\n  margin-left: 25%;\n}\n\n.text {\n  color: white;\n  opacity: 0;\n  transition: 0.5s;\n}\n\n.card:hover .content {\n  clip-path: polygon(100% 0, 100% 50%, 100% 100%, 0% 100%, 0 50%, 0% 0%);\n}\n\n.card:hover .card-title {\n  padding-top: 1em;\n  margin-left: 0%;\n  transform: rotate(0deg);\n}\n\n.card:hover .text {\n  opacity: 1;\n}",
