    css: "/* From Uiverse.io by JoseIsra - Tags: card, flip */\n.card {\n  width: 12rem;\n  cursor: pointer;\n}\n\n.content {\n  text-align: center;\n  position: relative;\n  transition: all 2.25s;\n  background-color: rgb(127, 204, 240);\n  padding: 5em;\n  transform-style: preserve-3d;\n}\n\n.card:hover .content {\n  transform: rotateY(0.5turn);\n}\n\n.front,\n.back {\n  position: absolute;\n  top: 0;\n  left: 0;\n  bottom: 0;\n  right: 0;\n  padding: 2em;\n  transform-style: preserve-3d;\n  backface-visibility: hidden;\n}\n\n.title {\n  transform: translateZ(5rem);\n  font-size: 2rem;\n}\n\n.subtitle {\n  transform: translateZ(2rem);\n}\n\n.back {\n  transform: rotateY(0.5turn);\n  background-color: #009bff;\n}\n\n.description {\n  transform: translateZ(3rem);\n}",
