    author: "Kagamiie",
    source: "galaxy",
    html: "<article class=\"card\">\n  <div class=\"card-img\">\n    <div class=\"card-imgs pv delete\"></div>\n  </div>\n\n  <div class=\"project-info\">\n    <div class=\"flex\">\n      <div class=\"project-title\">Title card</div>\n      <span class=\"tag\">type</span>\n    </div>\n    <span class=\"lighter\"\n      >Lorem ipsum, dolor sit amet consectetur adipisicing elit. Repudiandae\n      voluptas ullam aut incidunt minima.</span\n    >\n  </div>\n</article>",
    css: "/* From Uiverse.io by Kagamiie  - Tags: simple, card, about me, profilecard */\n.project-info {\n  padding: 100px 40px;\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n  position: relative;\n  top: -50px;\n}\n\n.project-title {\n  font-weight: 500;\n  font-size: 1.5em;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  color: black;\n}\n\n.lighter {\n  font-size: 0.9em;\n}\n\n.flex {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n}\n\n.tag {\n  font-weight: lighter;\n  color: grey;\n}\n\n/*DELETE THIS TWO LINE*/\n.delete {\n  background-color: #b2b2fd;\n}\n\n.card-img div {\n  width: 90%;\n}\n/*IF USING IMAGES*/\n\n.card {\n  background-color: white;\n  color: black;\n  width: 300px;\n  max-height: 330px;\n  border-radius: 8px;\n  box-shadow: rgba(50, 50, 93, 0.25) 0px 50px 100px -20px,\n    rgba(0, 0, 0, 0.3) 0px 30px 60px -30px;\n}\n\n.card-img {\n  position: relative;\n  top: -20px;\n  height: 100px;\n  display: flex;\n  justify-content: center;\n}\n\n/* Change the .card-img div to .card-img img to use img*/\n.card-img a,\n.card-img div {\n  height: 150px;\n  width: 90%;\n  /* Change this width here to change the width of the color/image */\n  object-fit: cover;\n  border-radius: 8px;\n  box-shadow: rgba(149, 157, 165, 0.2) 0px 8px 24px;\n}\n\n.card-imgs {\n  transition: all 0.5s;\n}",
