    author: "Kemboi-Dun",
    source: "galaxy",
    html: "<div class=\"container\">\n    <div class=\"terminal_toolbar\">\n        <div class=\"butt\">\n            <button class=\"btn btn-color\"></button>\n            <button class=\"btn\"></button>\n            <button class=\"btn\"></button>\n        </div>\n        <p class=\"user\">johndoe@admin: ~</p>\n        <div class=\"add_tab\">\n            +\n        </div>\n    </div>\n    <div class=\"terminal_body\">\n        <div class=\"terminal_promt\">\n            <span class=\"terminal_user\">johndoe@admin:</span>\n            <span class=\"terminal_location\">~</span>\n            <span class=\"terminal_bling\">$</span>\n            <span class=\"terminal_cursor\"></span>\n        </div>\n    </div>\n</div>",
    css: "/* From Uiverse.io by Kemboi-Dun - Tags: card */\n.container {\n  width: 250px;\n  height: 250px;\n}\n\n.terminal_toolbar {\n  display: flex;\n  height: 30px;\n  align-items: center;\n  padding: 0 8px;\n  box-sizing: border-box;\n  border-top-left-radius: 5px;\n  border-top-right-radius: 5px;\n  background: #212121;\n  justify-content: space-between;\n}\n\n.butt {\n  display: flex;\n  align-items: center;\n}\n\n.btn {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  padding: 0;\n  margin-right: 5px;\n  font-size: 8px;\n  height: 12px;\n  width: 12px;\n  box-sizing: border-box;\n  border: none;\n  border-radius: 100%;\n  background: linear-gradient(#7d7871 0%, #595953 100%);\n  text-shadow: 0px 1px 0px rgba(255, 255, 255, 0.2);\n  box-shadow: 0px 0px 1px 0px #41403A, 0px 1px 1px 0px #474642;\n}\n\n.btn-color {\n  background: #ee411a;\n}\n\n.btn:hover {\n  cursor: pointer;\n}\n\n.btn:focus {\n  outline: none;\n}\n\n.butt--exit {\n  background: linear-gradient(#f37458 0%, #de4c12 100%);\n}\n\n.add_tab {\n  border: 1px solid #fff;\n  color: #fff;\n  padding: 0 6px;\n  border-radius: 4px 4px 0 0;\n  border-bottom: none;\n  cursor: pointer;\n}\n\n.user {\n  color: #d5d0ce;\n  margin-left: 6px;\n  font-size: 14px;\n  line-height: 15px;\n}\n\n.terminal_body {\n  background: rgba(0, 0, 0, 0.6);\n  height: calc(100% - 30px);\n  padding-top: 2px;\n  margin-top: -1px;\n  font-size: 12px;\n  border-bottom-left-radius: 5px;\n  border-bottom-right-radius: 5px;\n}\n\n.terminal_promt {\n  display: flex;\n}\n\n.terminal_promt span {\n  margin-left: 4px;\n}\n\n.terminal_user {\n  color: #1eff8e;\n}\n\n.terminal_location {\n  color: #4878c0;\n}\n\n.terminal_bling {\n  color: #dddddd;\n}\n\n.terminal_cursor {\n  display: block;\n  height: 14px;\n  width: 5px;\n  margin-left: 10px;\n  animation: curbl 1200ms linear infinite;\n}\n\n@keyframes curbl {\n\n  0% {\n    background: #ffffff;\n  }\n\n  49% {\n    background: #ffffff;\n  }\n\n  60% {\n    background: transparent;\n  }\n\n  99% {\n    background: transparent;\n  }\n\n  100% {\n    background: #ffffff;\n  }\n}",
