    author: "LilaRest",
    source: "galaxy",
    html: "<div class=\"card\">\n  <div class=\"card-overlay\"></div>\n  <div class=\"card-inner\">YOUR<br>CONTENT<br>HERE</div>\n</div>",
    css: "/* From Uiverse.io by LilaRest - Tags: neumorphism, skeuomorphism, minimalist, card, thick, rounded, smooth, noise, paper, realistic */\n.card {\n  --bg: #e8e8e8;\n  --contrast: #e2e0e0;\n  --grey: #93a1a1;\n  position: relative;\n  padding: 9px;\n  background-color: var(--bg);\n  border-radius: 35px;\n  box-shadow: rgba(50, 50, 93, 0.25) 0px 50px 100px -20px, rgba(0, 0, 0, 0.3) 0px 30px 60px -30px, rgba(10, 37, 64, 0.35) 0px -2px 6px 0px inset;\n}\n\n.card-overlay {\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  background: repeating-conic-gradient(var(--bg) 0.0000001%, var(--grey) 0.000104%) 60% 60%/600% 600%;\n  filter: opacity(10%) contrast(105%);\n}\n\n.card-inner {\n  display: -webkit-box;\n  display: -ms-flexbox;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  overflow: hidden;\n  width: 190px;\n  height: 254px;\n  background-color: var(--contrast);\n  border-radius: 30px;\n  /* Content style */\n  font-size: 30px;\n  font-weight: 900;\n  color: #c7c4c4;\n  text-align: center;\n  font-family: monospace;\n}",
