    css: "/* From Uiverse.io by Lucaasbre  - Tags: minimalist, warning, card, modern, clean, confirm, modal, security */\n.confirm-div {\n  background-color: #ccc;\n}\n\n.green-btn {\n  background-color: #47a04b;\n}\n\n.green-btn:hover {\n  background-color: #368339;\n}\n\n.green-btn:active {\n  background-color: #2d6830;\n}\n\n.green-btn:disabled {\n  background-color: #c8eac9;\n  color: #1b7a43;\n}\n\n.red-btn {\n  background-color: #f93a3a;\n}\n\n.red-btn:hover {\n  background-color: #e71f1f;\n}\n\n.red-btn:active {\n  background-color: #c21313;\n}\n\n.red-btn:disabled {\n  background-color: #ffc7c7;\n  color: #c21313;\n}\n\n.confirm-div {\n  font-size: 14px;\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n  width: 300px;\n  padding: 20px;\n  text-align: center;\n  border-radius: 6px;\n  box-shadow: 4px 4px 15px #3e3e3e;\n  font-family: \"Segoe UI\", Tahoma, sans-serif;\n  cursor: default;\n}\n\n.confirm-div button {\n  cursor: pointer;\n  width: 100%;\n  padding: 4px 6px;\n  border-radius: 4px;\n  color: #fff;\n  border: none;\n  height: 30px;\n  width: 100%;\n}\n\n.confirm-div p {\n  display: flex;\n  flex-direction: column;\n}\n\n.confirm-div p strong {\n  margin-bottom: 15px;\n}\n\n.warning-general {\n  position: absolute; /* switch to fixed */\n  top: 0;\n  left: 0;\n  z-index: 999;\n  width: 100%;\n  height: 100%;\n  backdrop-filter: blur(2px);\n}\n\n.modals-container {\n  display: flex;\n  flex-direction: row;\n  height: 32px;\n  margin-top: 20px;\n  gap: 7px;\n  width: 100%;\n}",
