    author: "Mizohack",
    source: "galaxy",
    html: "<div class=\"wrapper\">\n  <div class=\"display\">\n    <div id=\"time\"></div>\n  </div>\n  <span></span>\n  <span></span>\n</div>",
    css: "/* From Uiverse.io by Mizohack  - Tags: card */\n.wrapper {\n  height: 100px;\n  width: 240px;\n  position: relative;\n  background: linear-gradient(135deg, #14ffe9, #ffeb3b, #ff00e0);\n  border-radius: 10px;\n  cursor: default;\n  animation: animate 1.5s linear infinite;\n}\n.wrapper .display,\n.wrapper span {\n  position: absolute;\n  top: 50%;\n  left: 50%;\n  transform: translate(-50%, -50%);\n}\n.wrapper .display {\n  z-index: 999;\n  height: 85px;\n  width: calc(100% - 16px);\n  background: #1b1b1b;\n  border-radius: 6px;\n  text-align: center;\n}\n.display #time {\n  line-height: 85px;\n  color: #fff;\n  font-size: 50px;\n  font-weight: 600;\n  letter-spacing: 1px;\n  background: linear-gradient(135deg, #14ffe9, #ffeb3b, #ff00e0);\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n  animation: animate 1.5s linear infinite;\n}\n@keyframes animate {\n  100% {\n    filter: hue-rotate(360deg);\n  }\n}\n.wrapper span {\n  height: 100%;\n  width: 100%;\n  border-radius: 10px;\n  background: inherit;\n}\n.wrapper span:first-child {\n  filter: blur(7px);\n}\n.wrapper span:last-child {\n  filter: blur(20px);\n}",
