    author: "NlghtM4re",
    source: "galaxy",
    html: "<div class=\"container\"> \n  <div class=\"window\"> \n    <div class=\"window-title\">\n      <p>Console Window</p>\n      <div class=\"window-buttons\">\n        <div class=\"window-button fullscreen\"></div>\n        <div class=\"window-button reduce\"></div>\n        <div class=\"window-button close\"></div>\n      </div>\n    </div>\n    <div class=\"console\">\n      <pre><code>def main():\n  for i in range(100):\n    print(f\"Add to favorites {i}\")\n    if favorite = true:\n      Favorite()\n\ndef Favorite():\n  print(\"thanks\")\n\nmain()</code></pre>\n    </div>\n  </div>\n</div>",
    css: "/* From Uiverse.io by NlghtM4re - Tags: green, card, code, menu */\n.container {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n}\n\n.window {\n  position: absolute;\n  height: 200px;\n  width: 300px;\n  background-color: #fff;\n  border: 2px solid #333;\n  border-radius: 15px;\n  overflow: hidden;\n}\n\n.window-title {\n  height: 30px;\n  background-color: #333;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0 10px;\n  box-shadow: 0px 2px 2px rgba(0, 0, 0, 0.25);\n}\n\n.window-title p {\n  color: #fff;\n  font-weight: bold;\n  margin: 0;\n  padding: 0;\n  text-align: left;\n}\n\n.window-buttons {\n  display: flex;\n  align-items: center;\n}\n\n.window-button {\n  width: 10px;\n  height: 10px;\n  border-radius: 5px;\n  margin: 5px;\n  transition: background-color 0.2s ease;\n}\n\n.window-button.close {\n  background-color: #f00;\n}\n\n.window-button.close:hover {\n  background-color: rgb(182, 2, 2);\n  cursor: pointer;\n}\n\n.window-button.reduce {\n  background-color: #ff0;\n}\n\n.window-button.reduce:hover {\n  background-color: rgb(172, 172, 4);\n  cursor: pointer;\n}\n\n.window-button.fullscreen {\n  background-color: #0f0;\n}\n\n.window-button.fullscreen:hover {\n  background-color: rgb(7, 159, 7);\n  cursor: pointer;\n}\n\n.window-button:focus {\n  outline: none;\n}\n\n.console {\n  width: 100%;\n  height: calc(100% - 30px);\n  background-color: #000;\n  color: #fff;\n  overflow: auto;\n}\n\n.console pre {\n  margin: 0;\n  padding: 5px;\n  font-size: 15px;\n}\n\n.console pre code {\n  color: #0f0;\n  outline: none;\n}\n\n.console::-webkit-scrollbar {\n  width: 8px;\n}\n\n.console::-webkit-scrollbar-track {\n  background-color: #333;\n}\n\n.console::-webkit-scrollbar-thumb {\n  background-color: #666;\n  border-radius: 10px;\n  border: 2px solid #333;\n}\n\n.console::-webkit-scrollbar-thumb:hover {\n  background-color: #999;\n}",
