    css: "/* From Uiverse.io by alexruix - Tags: card */\n/*Magic card*/\n.card {\n width: 190px;\n height: 254px;\n background: #f5f5f5;\n overflow: visible;\n box-shadow: 0 5px 20px 2px rgba(0,0,0,0.1);\n display: flex;\n flex-direction: column;\n align-items: center;\n}\n\n.card-info {\n display: flex;\n flex-direction: column;\n align-items: center;\n gap: 2em;\n padding: 0 1rem;\n}\n\n.card-img {\n --size: 100px;\n width: var(--size);\n height: var(--size);\n border-radius: 50%;\n transform: translateY(-50%);\n background: #42caff;\n background: linear-gradient(to bottom, #42caff 0%, #e81aff 100%);\n position: relative;\n transition: all .3s ease-in-out;\n}\n\n.card-img::before {\n content: \"\";\n border-radius: inherit;\n position: absolute;\n top: 50%;\n left: 50%;\n width: 90%;\n height: 90%;\n transform: translate(-50%, -50%);\n border: 1rem solid #e8e8e8;\n}\n\n/*Text*/\n.text-title {\n text-transform: uppercase;\n font-size: 0.75em;\n color: #42caff;\n letter-spacing: 0.05rem;\n}\n\n.text-body {\n font-size: .8em;\n text-align: center;\n color: #6f6d78;\n font-weight: 400;\n font-style: italic;\n}\n\n/*Hover*/\n.card:hover .card-img {\n --size: 110px;\n width: var(--size);\n height: var(--size);\n}",
