    html: "<div class=\"one-div\"></div>",
    css: "/* From Uiverse.io by andrew-demchenk0 - Tags: gradient, spinner, animated, uiverse, transition, spin, ui, points, creator points */\n.one-div {\n  cursor: help;\n  position: relative;\n  width: 185px;\n  height: 30px;\n  border-radius: 10px;\n  background: linear-gradient(120deg,\n    #BF66FF 0%, \n    #6248FF 3%,\n    #00DDEB 95%\n    );\n  animation: spin 4s linear infinite;\n  transform: translateY(100px);\n  box-shadow: 0px 10px 25px -10px #4E67FB;\n  transform-style: preserve-3d;\n  transition: all 0.4s;\n}\n\n.one-div::before {\n  content: 'U';\n  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;\n  font-weight: 900;\n  font-size: 200px;\n  display: inline-block;\n  background-image: linear-gradient(140deg,\n    #BF66FF 10%, \n    #6248FF 70%,\n    #00DDEB 100%\n    );\n  background-clip: text;\n  -webkit-background-clip: text;\n  color: transparent;\n  position: absolute;\n  bottom: 10px;\n  left: -10px;\n}\n\n.one-div::after {\n  display: block;\n  content: '';\n  width: 35px;\n  height: 147px;\n  border-radius: 0 0 10px 10px;\n  background: linear-gradient(140deg,\n    #BF66FF -100%, \n    #6248FF 40%,\n    #00DDEB 100%\n    );\n  position: absolute;\n  bottom: 50px;\n  right: 0;\n}\n\n@keyframes spin {\n  0% {\n    transform: rotateY(0deg) translateY(100%);\n  }\n\n  100% {\n    transform: rotateY(360deg) translateY(100%);\n  }\n}\n\n@keyframes spin2 {\n  0% {\n    transform: translateY(-20%) rotateY(0);\n  }\n\n  100% {\n    transform: translateY(-20%) rotateY(360deg);\n  }\n}\n\n.one-div:active {\n  cursor: wait;\n  width: 100px;\n  height: 100px;\n  border-radius: 200px;\n  animation: spin2 2.5s linear infinite;\n  background: linear-gradient(145deg,\n    #BF66FF 10%, \n    #6248FF 50%,\n    #00DDEB 100%\n  );\n}\n\n.one-div:active::before {\n  font-size: 0px;\n  left: 10px;\n  top: 10px;\n  width: 80px;\n  height: 80px;\n  border-radius: 50%;\n  /* background: #e8e8e8; */\n  background: #212121;\n}\n\n.one-div:active::after {\n  width: 20px;\n  height: 20px;\n  background: transparent;\n  transform: rotate(45deg);\n  border: 10px solid;\n  border-image: linear-gradient(85deg,\n    #BF66FF -50%, \n    #6248FF 80%,\n    #00DDEB 150%\n    )1;\n  border-radius: 0;\n  top: calc(50% - 20px);\n  left: calc(50% - 20px);\n}",
