    author: "eslam-hany",
    source: "galaxy",
    html: "<div class=\"card\">HOVER</div>",
    css: "/* From Uiverse.io by eslam-hany - Tags: card */\n.card {\n  position: relative;\n  width: 220px;\n  height: 320px;\n  background: mediumturquoise;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 25px;\n  font-weight: bold;\n  border-radius: 15px;\n  cursor: pointer;\n}\n\n.card::before,\n.card::after {\n  position: absolute;\n  content: \"\";\n  width: 20%;\n  height: 20%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 25px;\n  font-weight: bold;\n  background-color: lightblue;\n  transition: all 0.5s;\n}\n\n.card::before {\n  top: 0;\n  right: 0;\n  border-radius: 0 15px 0 100%;\n}\n\n.card::after {\n  bottom: 0;\n  left: 0;\n  border-radius: 0 100%  0 15px;\n}\n\n.card:hover::before,\n.card:hover:after {\n  width: 100%;\n  height: 100%;\n  border-radius: 15px;\n  transition: all 0.5s;\n}\n\n.card:hover:after {\n  content: \"HELLO\";\n}",
