    css: "/* From Uiverse.io by eslam-hany - Tags: card */\n.book {\n  position: relative;\n  border-radius: 10px;\n  width: 220px;\n  height: 300px;\n  background-color: whitesmoke;\n  -webkit-box-shadow: 1px 1px 12px #000;\n  box-shadow: 1px 1px 12px #000;\n  -webkit-transform: preserve-3d;\n  -ms-transform: preserve-3d;\n  transform: preserve-3d;\n  -webkit-perspective: 2000px;\n  perspective: 2000px;\n  display: -webkit-box;\n  display: -ms-flexbox;\n  display: flex;\n  -webkit-box-align: center;\n  -ms-flex-align: center;\n  align-items: center;\n  -webkit-box-pack: center;\n  -ms-flex-pack: center;\n  justify-content: center;\n  color: #000;\n}\n\n.cover {\n  top: 0;\n  position: absolute;\n  background-color: lightgray;\n  width: 100%;\n  height: 100%;\n  border-radius: 10px;\n  cursor: pointer;\n  -webkit-transition: all 0.5s;\n  transition: all 0.5s;\n  -webkit-transform-origin: 0;\n  -ms-transform-origin: 0;\n  transform-origin: 0;\n  -webkit-box-shadow: 1px 1px 12px #000;\n  box-shadow: 1px 1px 12px #000;\n  display: -webkit-box;\n  display: -ms-flexbox;\n  display: flex;\n  -webkit-box-align: center;\n  -ms-flex-align: center;\n  align-items: center;\n  -webkit-box-pack: center;\n  -ms-flex-pack: center;\n  justify-content: center;\n}\n\n.book:hover .cover {\n  -webkit-transition: all 0.5s;\n  transition: all 0.5s;\n  -webkit-transform: rotatey(-80deg);\n  -ms-transform: rotatey(-80deg);\n  transform: rotatey(-80deg);\n}\n\np {\n  font-size: 20px;\n  font-weight: bolder;\n}",
