    html: "<div class=\"card\">\n  <div class=\"main-content\">\n    <div class=\"header\">\n  <span>Article on</span>\n  <span>29-June-2023</span>\n</div>\n<p class=\"heading\">Different ways to use CSS in React</p>\n<div class=\"categories\">\n  <span>React</span>\n  <span>Css</span>\n</div>\n  </div>\n<div class=\"footer\">\n  by Harsh Gupta\n</div>\n</div>",
