    css: "/* From Uiverse.io by gharsh11032000  - Tags: card, hover, hover effect, card template, cool card, cardhover , card animation, card hover */\n.card {\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 320px;\n  border-radius: 24px;\n  line-height: 1.6;\n  transition: all 0.64s cubic-bezier(0.23, 1, 0.32, 1);\n}\n.content {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 24px;\n  padding: 36px;\n  border-radius: 24px;\n  background: transparent;\n  color: #000000;\n  z-index: 1;\n  transition: all 0.64s cubic-bezier(0.23, 1, 0.32, 1);\n}\n.card::before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  left: 0;\n  background-color: #0a3cff;\n  border-radius: inherit;\n  height: 100%;\n  width: 100%;\n  opacity: 0;\n  transform: skew(-24deg);\n  clip-path: circle(0% at 50% 50%);\n  transition: all 0.64s cubic-bezier(0.23, 1, 0.32, 1);\n}\n.content .heading {\n  font-weight: 700;\n  font-size: 36px;\n  line-height: 1.3;\n  z-index: 1;\n}\n.content .para {\n  z-index: 1;\n  opacity: 0.8;\n  font-size: 18px;\n}\n.content .para-sm {\n  font-size: 16px;\n}\n.card:hover::before {\n  opacity: 1;\n  transform: skew(0deg);\n  clip-path: circle(140.9% at 0 0);\n}\n.card:hover .content {\n  color: #ffffff;\n}",
