    author: "kamehame-ha",
    source: "galaxy",
    html: "<div class=\"cards\">\n    <div class=\"card red\">\n        <p class=\"tip\">Hover Me</p>\n        <p class=\"second-text\">Lorem Ipsum</p>\n    </div>\n    <div class=\"card blue\">\n        <p class=\"tip\">Hover Me</p>\n        <p class=\"second-text\">Lorem Ipsum</p>\n    </div>\n    <div class=\"card green\">\n        <p class=\"tip\">Hover Me</p>\n        <p class=\"second-text\">Lorem Ipsum</p>\n    </div>\n</div>",
    css: "/* From Uiverse.io by kamehame-ha - Tags: simple, animated, clean, sample */\n.cards {\n  display: flex;\n  flex-direction: column;\n  gap: 15px;\n}\n\n.cards .red {\n  background-color: #f43f5e;\n}\n\n.cards .blue {\n  background-color: #3b82f6;\n}\n\n.cards .green {\n  background-color: #22c55e;\n}\n\n.cards .card {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-direction: column;\n  text-align: center;\n  height: 100px;\n  width: 250px;\n  border-radius: 10px;\n  color: white;\n  cursor: pointer;\n  transition: 400ms;\n}\n\n.cards .card p.tip {\n  font-size: 1em;\n  font-weight: 700;\n}\n\n.cards .card p.second-text {\n  font-size: .7em;\n}\n\n.cards .card:hover {\n  transform: scale(1.1, 1.1);\n}\n\n.cards:hover > .card:not(:hover) {\n  filter: blur(10px);\n  transform: scale(0.9, 0.9);\n}",
