    css: "/* From Uiverse.io by shahbaz4783  - Tags: simple, material design, green, card, product, card template */\n.job-card {\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  gap: 1.2em;\n  box-shadow: #091e4240 0px 1px 1px, #091e4221 0px 0px 1px 1px;\n  border-radius: 0.6em;\n  padding: 1em;\n  max-width: 30em;\n}\n\n.text-title {\n  display: -webkit-box;\n  -webkit-line-clamp: 1;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n  font-size: 1.25em;\n  font-weight: 600;\n  font-family: \"Noto Sans\", sans-serif;\n}\n\n.text-body {\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n  font-family: \"Poppins\", sans-serif;\n  letter-spacing: 0.4px;\n}\n\n.post-date {\n  color: #598551;\n}\n\n.budget-exp {\n  display: flex;\n  gap: 5em;\n}\n\n.budget-exp .value {\n  font-size: 1em;\n  font-weight: 600;\n}\n\n.budget-exp .label {\n  font-size: 1em;\n  color: #598551;\n}\n\n.card-btn {\n  border: none;\n  font-size: 1rem;\n  background-color: green;\n  color: white;\n  cursor: pointer;\n  transition: all 0.3s ease;\n  border-radius: 2em;\n  padding: 0.6em 1em;\n}\n\n.card-btn:hover {\n  background-color: #026602;\n}\n\n.tags article {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.6em;\n}\n\n.tags p {\n  border-radius: 1.2em;\n  padding: 0.2em 0.5em;\n  background-color: #f2f7f2;\n  color: #598551;\n}",
