    css: "/* From Uiverse.io by vinodjangid07 - Tags: card, cookies, popup */\n.card {\n  width: 300px;\n  height: 220px;\n  background-color: rgb(255, 255, 255);\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  padding: 20px 30px;\n  gap: 13px;\n  position: relative;\n  overflow: hidden;\n  box-shadow: 2px 2px 20px rgba(0, 0, 0, 0.062);\n}\n\n#cookieSvg {\n  width: 50px;\n}\n\n#cookieSvg g path {\n  fill: rgb(97, 81, 81);\n}\n\n.cookieHeading {\n  font-size: 1.2em;\n  font-weight: 800;\n  color: rgb(26, 26, 26);\n}\n\n.cookieDescription {\n  text-align: center;\n  font-size: 0.7em;\n  font-weight: 600;\n  color: rgb(99, 99, 99);\n}\n\n.buttonContainer {\n  display: flex;\n  gap: 20px;\n  flex-direction: row;\n}\n\n.acceptButton {\n  width: 80px;\n  height: 30px;\n  background-color: #7b57ff;\n  transition-duration: .2s;\n  border: none;\n  color: rgb(241, 241, 241);\n  cursor: pointer;\n  font-weight: 600;\n  border-radius: 20px;\n}\n\n.declineButton {\n  width: 80px;\n  height: 30px;\n  background-color: rgb(218, 218, 218);\n  transition-duration: .2s;\n  color: rgb(46, 46, 46);\n  border: none;\n  cursor: pointer;\n  font-weight: 600;\n  border-radius: 20px;\n}\n\n.declineButton:hover {\n  background-color: #ebebeb;\n  transition-duration: .2s;\n}\n\n.acceptButton:hover {\n  background-color: #9173ff;\n  transition-duration: .2s;\n}",
