    css: "/* From Uiverse.io by yariklnv - Tags: card, box, div */\n@keyframes rotate {\n  from {\n    transform: rotateZ(0deg);\n  }\n\n  to {\n    transform: rotateZ(360deg);\n  }\n}\n\n.border {\n  background-image: linear-gradient(to left, red, blue);\n  width: 100px;\n  height: 100px;\n  border-radius: 20px;\n}\n\n.border::before {\n  background-image: linear-gradient(to left, red, blue);\n  content: \"\";\n  position: absolute;\n  z-index: -1;\n  height: 100px;\n  width: 100px;\n  scale: 1.1;\n  filter: blur(25px);\n  animation: rotate 4s linear infinite;\n  border-radius: 100px;\n}\n\n.content {\n  background-color: #111;\n  width: 100px;\n  height: 100px;\n  border-radius: 19px;\n  scale: 0.9;\n}",
